<script>
import CustomerService from '../modules/CustomerService.vue'
import telegramIcon from '@/assets/portal/proxy-icon1.png'
import usdtIcon from '@/assets/portal/USDT.png'
import hwApp from '@/assets/portal/汇旺转账2.webp'
import hwWallet from '@/assets/portal/汇旺转账2.webp'
import byWallet from '@/assets/portal/佰易钱包.webp'
import TitleLine from '../modules/TitleLine'
import USDIcon from '@/assets/portal/rechargeTutorial/USD.svg'
import USDTIcon from '@/assets/portal/rechargeTutorial/USDT.svg'
import USDTdisIcon from '@/assets/portal/rechargeTutorial/USDT_dis.svg'
import { getNewUordermons,webCzIndex,getSuppleUrl, getHuiOneinfo, getRgHuione, getOrder, getRgBaiyi, getUserInfo } from '@/api/user'
import QRCode from 'qrcodejs2'
import { Dialog } from 'vant'
export default {
  components: {
    CustomerService,
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      timeNum:5,
      timeInterval:null,
      showResultIng:false,
      showResultSuccess:false,
      showResultFail:false,
      cztime:'',
      rechargemons:'',
      rechargeAfterMons:'',
      needmonscz: '',
      themeColor:process.env.VUE_APP_THEME_COLOR,
      tipShow: false,
      showComfirm: false,
      currentRes: {},
      showCopyBtn: true,
      showCopySuccess: false,
      showService: false,
      imgUrl: '',
      title: this.$t('czym.czym01'),
      nameValue: '',
      addressValue: '',
      addressValueHw: '',
      tabList: [{ tab: this.$t('czym.czym04'),value:'1' }, { tab: this.$t('czym.czym05'),value:'2' }, { tab: this.$t('czym.czym06'),value:'3' }],
      payModeList: [
        { payMode: this.$t('czym.czym13'), index: 1, imgUrl: hwApp },  //汇旺转账
        { payMode: this.$t('czym.czym14'), index: 0, imgUrl: hwWallet },  //汇旺app
        { payMode: this.$t('czym.czym43'), index: 2, imgUrl: byWallet }], //佰易
      // payModeListBy: [{ payMode: '佰易转账' }],
      tabColor: '0',
      oldTabColor: '',
      payMode: 1,
      mons: 0,
      monsList: [
        // { mons: '10' }, { mons: '20' }, { mons: '30' }, { mons: '50' }, { mons: '80' }, { mons: '100' }
      ],
      monsInput: 10,
      monTypeList:[{icon:USDTIcon,disIcon: USDTdisIcon , label:'USDT',value:'1'},{icon:USDIcon,label:'USD',value:'0'}],
      monType:'1',
      huionescan:'',
      status: 'select',
      interval: null,
      interResult:null,
      endTime: '',
      telegramIcon: telegramIcon,
      coinList: [
        { coinName: 'USDT TRC20', coinImgUrl: usdtIcon, onChoose: true }
        // { coinName: 'ETH', coinImgUrl: ethIcon, onChoose: false },
        // { coinName: 'BTC', coinImgUrl: btcIcon, onChoose: false },
        // { coinName: 'SOL', coinImgUrl: solIcon, onChoose: false },
        // { coinName: 'BNB', coinImgUrl: bnbIcon, onChoose: false }
      ],
      isopenhwrgcz: true,
      isopenhwscan: true,
      isopenbaiyi: true
    }
  },
  watch: {
    // 监听 activeIndex 的变化
    tabColor(newVal, oldVal) {
      // oldVal: 切换前的旧索引
      // newVal: 切换后的新索引
      this.oldTabColor = oldVal
    },
    showResultIng(newVal){
      if(!newVal){
        clearInterval(this.interResult)
      }
    }
  },
  async created() {
    const res = await getUserInfo()
    this.tipShow = res.isnewuserhd === '1'
    webCzIndex().then(res => {
      this.monsList = res.moneylist.slice(0,6).map((item)=>{
        return {mons:item.money}
      })
      this.needmonscz=res.needmonscz
      const arr=[]
      const subarr=[]
      // res.czlevel1.split(';').forEach((element,index) => {
      //   const ele = this.tabList.find(item => item.tab === element)
      //   arr.push(ele)
      //   if(element===this.$t('czym.czym05')){ //汇旺-佰易
      //     res.czlevel2.split(';')[index].split(',').forEach(item => {
      //       const subEle = this.payModeList.find(obj => obj.payMode === item)
      //       subarr.push(subEle)
      //     })
      //   }
      // });
      res.orderlist.forEach(element => {
        const ele = this.tabList.find(item => item.value === element.type)
        if (ele) {
          // 如果 ele 存在，才设置属性
          ele.tab = element.name
          arr.push(ele)
        } else {
            // 建议：处理未找到匹配项的情况，比如打印警告
            console.warn(`未能在 tabList 中找到匹配的类型: ${element.type}`);
            return; // 跳过当前循环的剩余代码
        }
        // ele.tab = element.name
        // arr.push(ele)
        if(element.type==='2'){ //汇旺-佰易
          element.types.forEach(item => {
            if(item.type==='4'){
              const subEle = this.payModeList.find(obj => obj.index === 2)
              subEle.payMode = item.name
              subarr.push(subEle)
            }else if(item.type==='3'){
              const subEle = this.payModeList.find(obj => obj.index === 0)
              subEle.payMode = item.name
              subarr.push(subEle)
            }else if(item.type==='2'){
              const subEle = this.payModeList.find(obj => obj.index === 1)
              subEle.payMode = item.name
              subarr.push(subEle)
            }
          })
        }
      })
      this.payModeList=subarr
      this.tabList = arr
    })
    // getRgHuione().then(res => {
    //   this.monsList = res.moneylist.slice(0,6).map((item)=>{
    //     return {mons:item.money}
    //   })
    //   this.isopenhwrgcz = res.isopenhwrgcz === '1'
    //   this.isopenhwscan = res.isopenhwscan === '1'
    //   if (!this.isopenhwrgcz) {
    //     // 隐藏汇旺转账
    //     this.payModeList=this.payModeList.filter(item=>item.index!==1)
    //   }
    //   if (!this.isopenhwscan) {
    //     // 隐藏汇旺扫码
    //     this.payModeList=this.payModeList.filter(item=>item.index!==0)
    //   }
    // })
    // getRgBaiyi().then(res => {
    //   this.isopenbaiyi = res.isopenbaiyi === '1'
    //   if (!this.isopenbaiyi) {
    //     // 隐藏佰易钱包
    //     this.payModeList=this.payModeList.filter(item=>item.index!==2)
    //   }
    // })
  },
  async mounted() {
    const res = await getSuppleUrl()
    this.addressValue = res.suppleurl
    // this.addressValue = 'TFX5EoqRufMYRkmpnhfh33L6L2z7Go3bEf'
    var qrcode = new QRCode(this.$refs.qrcode, {
      text: this.addressValue, // xxx为设置要生成二维码的链接
      width: 146,
      height: 146,
      colorDark: '#000000',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.H
    })
  },
  beforeDestroy() {
    if (this.interval) {
      clearInterval(this.interval)
    }
    if (this.interResult) {
      clearInterval(this.interResult)
    }
    if (this.timeInterval) {
      clearInterval(this.timeInterval)
    }
  },
  methods: {
    closeDig(){
      clearInterval(this.timeInterval)
      this.showResultSuccess=false
    },
    returnHome(){
      clearInterval(this.timeInterval);
      this.$router.push('/home')
    },
    searchResult(){
      let times=30
      this.showResultIng=true
      //接口返回数据没有值，需要重新请求数据
      if(this.interResult){
        clearInterval(this.interResult)
      }
      this.interResult = setInterval(async() => {
        const res = await getNewUordermons()
        if (Number(res.mons)>0) {
          this.cztime = res.cztime
          this.rechargemons = res.mons
          this.rechargeAfterMons = res.curmons
          clearInterval(this.interResult)
          this.showResultIng=false
          this.showResultSuccess=true
          this.timeCal()
        }else if(times===0){
          clearInterval(this.interResult)
          this.showResultIng=false
          this.showResultFail=true
        }
        times--
      }, 3 * 1000)
    },
    timeCal(){
      if (this.timeInterval) {
        clearInterval(this.timeInterval)
      }
      this.timeInterval = setInterval(() => {
        this.timeNum--
        if(this.timeNum===0){
          clearInterval(this.timeInterval)
          this.$router.push('/home')
        }
      }, 1000)
    },
    handleTabChange() { // 记录旧的索引值

    },
    onChooseCoin(item) {
      if (item.coinName !== 'USDT') {
        this.$toast.fail('暂不支持该币种')
        return
      }
    },
    openNew() {
      this.showService = true
      // window.open('https://t.me/rryl666')
    },
    async createOrderNow() {
      const res = await getHuiOneinfo({ mons: this.monsInput, type: this.monType })
      // this.status = 'confirm'
      // this.endTime = res.endtime
      // await this.$nextTick()
      // var qrcode1 = new QRCode(this.$refs.qrcode1, {
      //   text: res.backurl, // xxx为设置要生成二维码的链接
      //   width: 85,
      //   height: 85,
      //   colorDark: '#000000',
      //   colorLight: '#ffffff',
      //   correctLevel: QRCode.CorrectLevel.H
      // })
      // this.showComfirm=true
      this.currentRes = res
      this.openHuiOnePay()
    },
    openHuiOnePay() {
      this.showComfirm = false
      const res = this.currentRes
      const userAgent = navigator.userAgent || navigator.vendor || window.opera
      if (userAgent.match(/iPad/i) || userAgent.match(/iPhone/i) || userAgent.match(/iPod/i)) {
        // return 'iOS';
        // window.open(res.backurl88)
        window.location.href = res.backurl88
        // window.location.href = res.backurl88
        // setTimeout(() => {
        //   window.open(res.backurl88)
        // },100)
      } else if (userAgent.match(/Android/i)) {
        // return 'Android';
        window.location.href = res.backurl88
      } else {
        // return 'unknown';
        window.location.href = res.backurl88
      }
      if (this.interval) {
        clearInterval(this.interval)
      }
      this.interval = setInterval(async() => {
        const data = await getOrder({ orderid: res.orderid })
        if (data.orderstatus === '1') {
          clearInterval(this.interval)
          this.$toast.success(this.$t('czym.czym35'))
          if (localStorage.getItem('version') === 'new') {
            this.$router.push({ path: '/home' })
          } else {
            this.$router.push({ path: '/oldhome' })
          }
        }
      }, 5 * 1000)
    },
    async createOrder() {
      const res = await getHuiOneinfo({ mons: this.monsInput, type: this.monType })
      this.status = 'confirm'
      this.endTime = res.endtime
      await this.$nextTick()
